/*
 * test_loader.h - Load JSON test cases for DeepSeekV3 MoE verification
 *
 * Week 7: Communication - Pure C Implementation
 *
 * Uses a minimal JSON parser (included inline) to load test cases
 * generated by the Python scripts.
 */

#ifndef TEST_LOADER_H
#define TEST_LOADER_H

#include <stdlib.h>

/* ============================================================
 * Generic JSON value extraction
 * ============================================================ */

/*
 * Read entire file into a null-terminated string.
 * Caller must free the returned pointer.
 */
char *read_file(const char *filepath);

/*
 * Extract an integer value from JSON: "key": 123
 */
int json_get_int(const char *json, const char *key);

/*
 * Extract a float value from JSON: "key": 1.23
 */
float json_get_float(const char *json, const char *key);

/*
 * Extract a boolean value from JSON: "key": true/false
 * Returns 1 for true, 0 for false.
 */
int json_get_bool(const char *json, const char *key);

/*
 * Extract a flat float array from a nested JSON array.
 * Handles arbitrarily nested arrays like [[[1,2],[3,4]],[[5,6],[7,8]]].
 * Flattens all values into a single row-major float array.
 *
 * Parameters:
 *   json: the full JSON string
 *   key: the key name (e.g., "gate_proj_weight")
 *   out_count: receives the number of floats extracted
 *
 * Returns: malloc'd float array, caller must free.
 */
float *json_get_float_array(const char *json, const char *key, int *out_count);

/*
 * Extract a flat int array from a nested JSON array.
 * Same flattening behavior as json_get_float_array.
 */
int *json_get_int_array(const char *json, const char *key, int *out_count);

/*
 * Extract a string value from JSON: "key": "value"
 * Returns malloc'd string, caller must free.
 */
char *json_get_string(const char *json, const char *key);


/* ============================================================
 * Test result reporting
 * ============================================================ */

typedef struct {
    const char *test_name;
    int passed;
    float max_error;
    float mean_error;
    int num_values;
} TestResult;

/*
 * Compare two float arrays and report results.
 * Returns 1 if max_error <= tolerance, 0 otherwise.
 */
TestResult compare_outputs(const char *test_name,
                            const float *expected, const float *actual,
                            int n, float tolerance);

/*
 * Print a test result.
 */
void print_test_result(const TestResult *result, float tolerance);

#endif /* TEST_LOADER_H */
